{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "high_goal_achievement",
  "per_column": [
    {
      "name": "achievement_score",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "A continuous achievement measure is essentially the underlying quantity from which high_goal_achievement is derived; it restates/leaks the outcome rather than predicting it."
    },
    {
      "name": "status_is_completed",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "Whether the goal is completed is only knowable at/after the outcome and is nearly deterministic with achievement, constituting post-outcome leakage rather than a predictive signal."
    },
    {
      "name": "priority_is_high",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "A binary flag derived from priority is a legitimate ex-ante attribute that lies outside the focus and could plausibly correlate with achievement without restating it."
    },
    {
      "name": "completion_rate_high",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "This is a thresholded version of percent_complete, which is essentially the same construct as goal achievement; it is a deterministic restatement/leak of the focus."
    },
    {
      "name": "time_spent_ratio",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "Elapsed-time-over-total ratio is only fully known once the goal period concludes and correlates with completion progress; as computed here it reflects outcome-time information (leakage) rather than a clean ex-ante predictor."
    }
  ],
  "n_predictors": 1,
  "predictive_utility": 0.1,
  "rationale": "The set is dominated by restatements and post-outcome measures of achievement/completion (achievement_score, status_is_completed, completion_rate_high, time_spent_ratio), which leak the focus rather than predict it. Only priority_is_high is a genuine ex-ante predictor, and it is a single weak binarized feature, so the set provides little legitimate predictive leverage beyond the original columns."
}

